ns.Data.LockpickRules = {
  cap_per_level = 5,
  cast_time_s = 5,
  range_yd = 5,
  tools = {
    name = "Thieves' Tools",
    item_id = 5060,
    consumed = false,
    get = "Free from the level-16 lockpicking class quest, or bought (about 15 silver, conquestcapped: Rogue supply vendors in Stormwind, Orgrimmar and the Riverglades; warcrafttavern: a Shady Dealer; kickegg: trade goods vendors). Only one set; must be in your bags.",
    source_url = "https://conquestcapped.com/guides/wow-forever/wow-forever-lockpicking/",
    checked = "2026-11-19",
  },
  learn = "Pick Lock (spell 1804) from any Rogue trainer at level 16, free (conquestcapped, warcrafttavern). Client lists it at level 1 (wowfdb, kickegg); Icy Veins milestone puts the lockpicking class quest at 15. See core conflicts.",
  skill_line = "Lockpicking is its own secondary skill line with a spellbook tab (wowfdb abilities/utility).",
  cap_examples = {
    ["16"] = 80,
    ["20"] = 100,
    ["30"] = 150,
    ["40"] = 200,
    ["50"] = 250,
    ["60"] = 300,
    source_url = "https://conquestcapped.com/guides/wow-forever/wow-forever-lockpicking/",
    checked = "2026-11-19",
  },
  notes = { "Damage interrupts the 5 s cast. Skill points come only from the lock, not from looting; easy (grey) locks stop giving points.", "Tooltip colour of \"Locked\": red = too low, orange = point every time, yellow = most of the time, green = rarely, grey = never (conquestcapped). In beta some grey footlockers still gave points: try once.", "Footlockers/doors: right-click. Lockboxes in bags: cast Pick Lock and click the box. Other players' boxes: they put it in the bottom \"Will not be traded\" trade slot; you get the skill point, they keep the box (conquestcapped, kickegg, warcrafttavern).", "Dark Leather Gloves (item 4248, Leatherworking) raise the skill a little (conquestcapped).", "Divide the skill you need by five to get the level you need (conquestcapped).", "Without Thieves' Tools in your bags the spell does nothing; the tools look like a crafting material, so check your bank if missing (conquestcapped).", "Poison-quest chests: game data lists 70; players opened at 66 and failed at 55 (conquestcapped); Icy Veins class-quest guide says 75 is required. Get 80 (the cap at 16) before you go.", "Lock values used are Classic: the Forever Wowhead DB shows a placeholder of 1 for every chest (conquestcapped); kickegg cross-checked the anchors against the 70862 client Lock table (48 lockpicking locks, 1-300).", "Legacy perk Working Overtime raises skill-up chance for \"primary, secondary, or class-based tradeskill\" by up to 20% (wowfdb legacy); whether Lockpicking counts is not stated." },
  other_source_urls = { "https://wowforever.kickegg.net/articles/forever-rogue-lockpicking-guide", "https://www.warcrafttavern.com/forever/guides/lockpicking/", "https://wowfdb.com/classes/rogue/utility/", "https://www.icy-veins.com/wow-forever/rogue-class-quests", "https://wowfdb.com/legacy/" },
  source_url = "https://conquestcapped.com/guides/wow-forever/wow-forever-lockpicking/",
  checked = "2026-11-19",
}

