ns.Data.StealthNotes = {
  {
    title = "Sap no longer breaks Stealth",
    body = "Using Sap no longer breaks Stealth (still requires Stealth, out-of-combat Humanoids, 65 energy per wowfdb). Sap one mob and open on another while hidden. Sap cannot trigger weapon procs (wowfdb). Talent Quick Getaway lets you Sap 1 more target (wowfdb).",
